def fit(yy):
    Xf=F[K[0]:K[1]].reshape(-1,128); Y=torch.tensor(np.tile(yy,K[1]-K[0])).float()
    mu=Xf.mean(0); sd=Xf.std(0)+1e-6; Z=(Xf-mu)/sd
    w=torch.zeros(128,requires_grad=True); b=torch.zeros(1,requires_grad=True)
    opt=torch.optim.Adam([w,b],lr=0.05)
    for it in range(500):
        l=torch.nn.functional.binary_cross_entropy_with_logits(Z@w+b,Y)+1e-4*(w**2).sum(); opt.zero_grad(); l.backward(); opt.step()
    return (w/sd).detach(), (b-(w*mu/sd).sum()).detach()
